\copy (SELECT lower(u.email), q.code, aa.score, aa.answered, coalesce(replace(replace(aa.note, E'\n', ' '), ',', ';'), ''), to_char(aa.answered_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') FROM assessment_answer aa JOIN assessment a ON a.id = aa.assessment_id JOIN app_user u ON u.id = a.client_id JOIN question q ON q.id = aa.question_id WHERE lower(u.email) IN ('oussemalazez@client', 'youssefbenjmaa@client') AND a.year = 2026 AND a.version = 1 ORDER BY u.email, q.code) TO STDOUT WITH (FORMAT csv, HEADER false)
